import React, { useEffect, useState } from "react";

import { Home, List, BookOpen, Database, Menu, X, ChevronLeft, ArrowRight} from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from 'recharts';
import { Link, useLocation } from 'react-router-dom';
import { Box, Container, Grid, Typography, Select, MenuItem, FormControl, InputLabel } from "@mui/material";

// --- モックデータ ---
const trendData = [
  { name: '第6号', onePiece: 1.2, jjk: 2.1, mha: 2.8 },
  { name: '第7号', onePiece: 1.8, jjk: 1.5, mha: 3.0 },
  { name: '第8号', onePiece: 1.1, jjk: 2.3, mha: 1.5 },
  { name: '第9号', onePiece: 1.5, jjk: 2.0, mha: 2.2 },
  { name: '第10号', onePiece: 1.0, jjk: 1.8, mha: 2.5 },
];

// --- 型定義 ---
interface RankingItem {
  rank: number;
  title: string;
  isbn: string;
}

type DataRow = {
  [key: string]: any;
  title?: string;
  date?: string;
  week?: string;
};

type RankingRow = {
  issue_label: string;
  title: string;
  rank_num: number;
};

type SeriesRanking = {
  series: string;
  average: number;
};

export default function JumpDashboard() {
  // サイドバーの開閉状態を管理
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [viewMode, setViewMode] = useState<'home' | 'all'>('home');


    const [data, setData] = useState<DataRow[]>([]);
    const [datathisweek, setDataThisWeek] = useState<DataRow[]>([]);
    //const [rankThisWeek, setRankThisWeek] = useState<RankingRow>([]);
    const [displayPeriod, setDisplayPeriod] = useState<number>(4); // 表示期間（週数）
    const [filteredData, setFilteredData] = useState<DataRow[]>([]);
    const [topSeries, setTopSeries] = useState<string[]>([]);
    const [displayCount, setDisplayCount] = useState<number>(5); // 表示する作品数
    const [averageRankings, setAverageRankings] = useState<SeriesRanking[]>([]);

    // 各作品の表示状態を管理
    const [visibleSeries, setVisibleSeries] = useState<{ [key: string]: boolean }>({});

    useEffect(() => {
      //fetch("/past-ranking-data.csv")
      fetch("http://localhost:8080/ranking")
        .then((response) => response.json())
        .then((rows: RankingRow[]) => {
          // =========================================
          // ① issueごとにまとめて「横持ち」形式へ変換
          // =========================================
          const grouped: { [issue: string]: any } = {};

          rows.forEach((row) => {
          if (!grouped[row.issue_label]) {
            grouped[row.issue_label] = {
              title: row.issue_label,
            };
          }

          grouped[row.issue_label][row.title] = row.rank_num;
          });

          const parsedData = Object.values(grouped);

          // =========================================
          // ② 作品カラム取得
          // =========================================
          const seriesColumns = Array.from(
            new Set(rows.map((r) => r.title))
          );

          // =========================================
          // ③ 平均順位計算（今までと同じロジック）
          // =========================================
          const seriesRankings: {
            [key: string]: { sum: number; count: number };
          } = {};

            // 各作品の順位の合計とデータ数を集計
          parsedData.forEach((row: any) => {
            seriesColumns.forEach((series) => {
              if (!seriesRankings[series]) {
                seriesRankings[series] = { sum: 0, count: 0 };
              }

              const rank = row[series];
              if (typeof rank === "number") {
                seriesRankings[series].sum += rank;
                seriesRankings[series].count += 1;
              }
            });
          });

          // 平均順位を計算してソート
          const rankings = Object.entries(seriesRankings)
            .map(([series, stats]) => ({
              series,
              average: stats.sum / stats.count,
            }))
            .sort((a, b) => a.average - b.average);// 平均順位が低い（上位の）順にソート

          setAverageRankings(rankings);


          // 上位作品の選出
          const topSeriesNames = rankings
          .slice(0, displayCount)
          .map((item) => item.series);

          setTopSeries(topSeriesNames);

          const initialVisibility = seriesColumns.reduce(
            (acc, series) => ({
              ...acc,
              [series]: topSeriesNames.includes(series),
            }),
            {}
          );

          setVisibleSeries(initialVisibility);

          setData(parsedData);
          setFilteredData(parsedData.slice(0, displayPeriod));
        }); // then


      //fetch("/new-ranking-data.csv")
      // 今週の連載順位
      /**fetch("/jumprank/new-ranking-data.csv")
        .then((response) => response.text())
        .then((csvText) => {
          const parsed = Papa.parse(csvText, {
            header: true,
            skipEmptyLines: true,
            dynamicTyping: true,
          });
          setDataThisWeek(parsed.data as DataRow[]);
        });*/

      fetch("http://localhost:8080/ranking?latest=true")
        .then((response)=>response.json())
        .then((jsonData)=>{
          setDataThisWeek(jsonData);
        });


    }, [displayCount]);

    // 表示期間が変更されたときのフィルタリング
    useEffect(() => {
      if (data.length > 0) {
        setFilteredData(data.slice(0, displayPeriod));
      }
    }, [displayPeriod, data]);

    // テーブルのカラム名を取得（データが空の場合は空配列）
    const label = datathisweek.length > 0 ? datathisweek[0].issue_label : [];
    const columns = datathisweek.length > 0 ? Object.keys(datathisweek[0]) : [];



  // 本来は fetch や import で読み込む JSON データ
  const jsonData = {
    issue: "2026年 第10号",
    rankings: [
      { rank: 1, title: "ONE PIECE", isbn: "978-4-08-884013-0" },
      { rank: 2, title: "呪術廻戦", isbn: "978-4-08-883595-2" },
      { rank: 3, title: "僕のヒーローアカデミア", isbn: "978-4-08-883842-7" },
      { rank: 4, title: "サカモトデイズ", isbn: "978-4-08-884013-0" },
      { rank: 5, title: "アオのハコ", isbn: "978-4-08-883000-0" },
      { rank: 6, title: "夜桜さんちの大作戦", isbn: "..." },
      { rank: 7, title: "アンデッドアンラック", isbn: "..." },
      { rank: 8, title: "新退戦", isbn: "..." }
    ]
  };

  // 共通のスタイル定数
  const colors = {
    bg: '#0f172a',
    sidebar: '#1a2235',
    content: '#161d2f',
    accent: '#3b82f6',
    border: '#2d3748',
    textMuted: '#94a3b8'
  };

  // 共通レイアウトスタイル
  const sidebarStyle: React.CSSProperties = {
    width: '240px',
    backgroundColor: colors.sidebar,
    position: 'fixed',
    height: '100vh',
    left: isSidebarOpen ? '0' : '-240px',
    transition: 'left 0.3s ease',
    zIndex: 90,
    paddingTop: '80px',
    borderRight: `1px solid ${colors.border}`,
    boxShadow: isSidebarOpen ? '10px 0 30px rgba(0,0,0,0.5)' : 'none'
  };


  const location = useLocation(); // 現在のパスを取得して「アクティブ状態」を判定する

  return (
    <div style={{ 
      display: 'flex', 
      backgroundColor: colors.bg, 
      minHeight: '100vh', 
      color: 'white', 
      fontFamily: 'sans-serif',
      position: 'relative',
      overflowX: 'hidden'
    }}>

      {/* ハンバーガーメニューボタン（モバイル・デスクトップ共通） */}
      <button 
        onClick={() => setSidebarOpen(!isSidebarOpen)}
        style={{
          position: 'fixed',
          top: '20px',
          left: '20px',
          zIndex: 100,
          backgroundColor: colors.sidebar,
          border: `1px solid ${colors.border}`,
          borderRadius: '4px',
          padding: '8px',
          cursor: 'pointer',
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
      </button>

    {/* サイドバー（ドロワー形式） */}
    <aside style={sidebarStyle}>
    <div style={{ padding: '0 24px', marginBottom: '30px', fontSize: '18px', fontWeight: 'bold' }}>
      ジャンプ順位管理
    </div>
    <nav>
      {[
        { icon: <Home size={18}/>, label: "ホーム", path: "/jumprank", mode: 'home' as const },
        { icon: <List size={18}/>, label: "号別ランキング", path: "/jumprank/issue", mode: 'all' as const },
        { icon: <BookOpen size={18}/>, label: "作品一覧", path: "/jumprank/series", mode: 'all' as const },
        { icon: <Database size={18}/>, label: "データ管理", path: "/jumprank/series", mode: 'home' as const }
      ].map((item, i) => {
        // 現在のパスと一致しているか判定
        const isActive = location.pathname === item.path;

        return (
          <Link 
            key={i} 
            to={item.path}
            // ページ遷移と同時にサイドバーを閉じる
            onClick={() => setSidebarOpen(false)}
            style={{ 
              display: 'flex', 
              alignItems: 'center', 
              gap: '12px', 
              padding: '15px 24px', 
              cursor: 'pointer', 
              textDecoration: 'none', // Link(a)タグの下線を消す
              color: isActive ? colors.accent : 'white', 
              backgroundColor: isActive ? 'rgba(59, 130, 246, 0.1)' : 'transparent',
              transition: 'background-color 0.2s',
              borderLeft: isActive ? `4px solid ${colors.accent}` : '4px solid transparent',
            }}
            onMouseOver={(e) => e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.05)'}
            onMouseOut={(e) => e.currentTarget.style.backgroundColor = isActive ? 'rgba(59, 130, 246, 0.1)' : 'transparent'}
          >
            <span style={{ display: 'flex', alignItems: 'center' }}>
              {item.icon}
            </span>
            <span style={{ fontSize: '14px', fontWeight: isActive ? 'bold' : 'normal' }}>
              {item.label}
            </span>
          </Link>
        );
      })}
    </nav>
  </aside>

      {/* オーバーレイ（サイドバーが開いている時に背景を暗くする） */}
      {isSidebarOpen && (
        <div 
          onClick={() => setSidebarOpen(false)}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.5)',
            zIndex: 80
          }}
        />
      )}

      {/* メインコンテンツ（中央のランキングのみ） */}
      <main style={{ 
        flex: 1, 
        padding: '80px 40px 40px 40px',
        maxWidth: '800px',
        margin: '0 auto',
        transition: 'margin-left 0.3s ease-in-out'
      }}>
        <header style={{ marginBottom: '40px' }}>
          <h2 style={{ fontSize: '28px', fontWeight: 'bold', marginBottom: '8px' }}>最新2026年 第10号</h2>
          <div style={{ width: '60px', height: '4px', backgroundColor: colors.accent }}></div>
        </header>
        {viewMode === 'home' ? (
          /* --- ホーム表示 --- */
          <>
            <h3 style={{ fontSize: '16px', color: colors.textMuted, marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ width: '4px', height: '16px', backgroundColor: colors.accent }}></span>
              {jsonData.issue}の順位表
            </h3>
            <div style={{ backgroundColor: colors.content, borderRadius: '12px', padding: '24px', border: `1px solid ${colors.border}` }}>
              {jsonData.rankings.slice(0, 5).map((item) => (
                <div key={item.rank} style={{ display: 'flex', alignItems: 'center', padding: '15px 0', borderBottom: `1px solid ${colors.border}` }}>
                  <span style={{ fontSize: '20px', fontWeight: 'bold', width: '40px', fontStyle: 'italic' }}>{item.rank}</span>
                  <span style={{ fontSize: '18px' }}>{item.title}</span>
                </div>
              ))}
              <button 
                onClick={() => setViewMode('all')}
                style={{ width: '100%', marginTop: '20px', padding: '12px', backgroundColor: '#252f48', border: 'none', borderRadius: '8px', color: 'white', cursor: 'pointer', fontWeight: 'bold' }}
              >
                全順位を見る
              </button>
            </div>
          </>
        ) : (
          /* --- 全順位テーブル表示 --- */
          <>
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '20px' }}>
              <button onClick={() => setViewMode('home')} style={{ background: 'none', border: 'none', color: colors.textMuted, cursor: 'pointer' }}>
                <ChevronLeft size={24} />
              </button>
              <h2 style={{ fontSize: '24px' }}>{jsonData.issue} 全順位</h2>
            </div>

            <div style={{ backgroundColor: colors.content, borderRadius: '12px', overflow: 'hidden', border: `1px solid ${colors.border}` }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ backgroundColor: 'rgba(255,255,255,0.05)', color: colors.textMuted, fontSize: '14px' }}>
                    <th style={{ padding: '15px 20px' }}>順位</th>
                    <th style={{ padding: '15px 20px' }}>作品名</th>
                    <th style={{ padding: '15px 20px' }}>リンク</th>
                  </tr>
                </thead>
                <tbody>
                  {jsonData.rankings.map((item) => (
                    <tr key={item.rank} style={{ borderBottom: `1px solid ${colors.border}` }}>
                      <td style={{ padding: '15px 20px', fontWeight: 'bold', fontStyle: 'italic', fontSize: '18px' }}>{item.rank}位</td>
                      <td style={{ padding: '15px 20px', fontSize: '16px' }}>{item.title}</td>
                      <td style={{ padding: '15px 20px' }}>
                        <a 
                          href={`https://www.shueisha.co.jp/books/items/contents.html?isbn=${item.isbn}`}
                          target="_blank" rel="noopener noreferrer"
                          style={{ color: colors.accent, textDecoration: 'none', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '4px' }}
                        >
                          公式 <ArrowRight size={14} />
                        </a>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}

        {/* トレンドグラフ */}
        <section>
          <h3 style={{ fontSize: '16px', color: colors.textMuted, marginBottom: '20px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span style={{ width: '4px', height: '16px', backgroundColor: colors.accent }}></span>
            トレンド推移
          </h3>
          <div style={{ 
            height: '250px', 
            backgroundColor: colors.content, 
            padding: '20px', 
            borderRadius: '12px',
            border: `1px solid ${colors.border}`
          }}>
          {/**   <ResponsiveContainer width="100%" height="100%">
              <LineChart data={trendData}>
                <CartesianGrid vertical={false} stroke={colors.border} strokeDasharray="3 3" />
                <XAxis dataKey="name" tick={{fill: colors.textMuted, fontSize: 12}} axisLine={false} tickLine={false} />
                <YAxis reversed domain={[1, 4]} hide />
                <Line type="monotone" dataKey="onePiece" stroke="#60a5fa" strokeWidth={3} dot={{r: 4, fill: '#fff'}} />
                <Line type="monotone" dataKey="jjk" stroke="#f87171" strokeWidth={2} dot={{r: 3}} />
                <Line type="monotone" dataKey="mha" stroke="#4ade80" strokeWidth={2} dot={{r: 3}} />
              </LineChart>
            </ResponsiveContainer>
          */}
      <ResponsiveContainer width="100%" height={400}>
        <LineChart data={filteredData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis 
            dataKey="title" 
            reversed={true}
            tick={{ fontSize: 12 }}
          />
          <YAxis 
            reversed={true}
            domain={[1, 'dataMax']}
            tickCount={10}
          />
          <Tooltip />
          <Legend 
            onClick={(e: any) => {
              if (e.dataKey && topSeries.includes(e.dataKey)) {
                setVisibleSeries(prev => ({
                  ...prev,
                  [e.dataKey as string]: !prev[e.dataKey as string]
                }));
              }
            }}
            formatter={(value, entry) => {
              if (!topSeries.includes(value)) return null;
              const isActive = visibleSeries[value];
              return (
                <span 
                  style={{ 
                    display: 'inline-flex',
                    alignItems: 'center',
                    cursor: 'pointer',
                    opacity: isActive ? 1 : 0.5,
                    transition: 'all 0.3s ease'
                  }}
                >
                  <span
                    style={{
                      display: 'inline-block',
                      width: '12px',
                      height: '12px',
                      marginRight: '8px',
                      backgroundColor: isActive ? entry.color : 'transparent',
                      border: `2px solid ${entry.color}`,
                      opacity: isActive ? 1 : 0.3,
                      transition: 'all 0.3s ease'
                    }}
                  />
                  <span style={{ 
                    color: isActive ? '#000000' : '#999999',
                    fontWeight: isActive ? 500 : 400
                  }}>
                    {value}
                  </span>
                </span>
              );
            }}
            wrapperStyle={{
              padding: '10px',
              borderRadius: '8px',
              backgroundColor: 'rgba(255, 255, 255, 0.9)'
            }}
          />
          {topSeries.map((series, index) => {
            const colors = [
              '#8884d8', '#d8681d', '#82ca9d', '#0fc7f0', '#6206e3',
              '#d213bf', '#55ff00', '#ff6b6b', '#4ecdc4', '#45b7d1'
            ];
            return (
              <Line
                key={series}
                type="monotone"
                dataKey={series}
                stroke={colors[index % colors.length]}
                strokeWidth={visibleSeries[series] ? 2 : 1}
                strokeOpacity={visibleSeries[series] ? 1 : 0.3}
                strokeDasharray={visibleSeries[series] ? "0" : "3 3"}
                dot={{ 
                  r: visibleSeries[series] ? 3 : 2,
                  strokeWidth: visibleSeries[series] ? 2 : 1,
                  strokeOpacity: visibleSeries[series] ? 1 : 0.3,
                  fill: visibleSeries[series] ? colors[index % colors.length] : "#fff"
                }}
                activeDot={visibleSeries[series] ? { r: 5 } : false}
              />
            );
          })}
        </LineChart>
      </ResponsiveContainer>

          </div>
        </section>
      </main>

    </div>
  );
}
